import React, { useEffect, useState } from 'react';
import Loading from '../../loading/Loading';
import CompanyMenu from '../Company_Menu/CompanyMenu';

const CompanyOrders = () => {
    const [loading, setLoading] = useState(true);
    const [orders, setOrders] = useState([]);
    const [formData, setFormData] = useState({
        customerName: '',
        productName: '',
        quantity: 0,
        price: 0,
        status: ''
    });

    useEffect(() => {
        // Simulación de carga de datos
        const timer = setTimeout(() => {
            setLoading(false);
            // Datos simulados de pedidos
            setOrders([
                {
                    id: 1,
                    customerName: 'Cliente A',
                    productName: 'Producto X',
                    quantity: 5,
                    price: 100,
                    status: 'Pendiente'
                },
                {
                    id: 2,
                    customerName: 'Cliente B',
                    productName: 'Producto Y',
                    quantity: 3,
                    price: 75,
                    status: 'En proceso'
                },
                {
                    id: 3,
                    customerName: 'Cliente C',
                    productName: 'Producto Z',
                    quantity: 2,
                    price: 50,
                    status: 'Completado'
                }
            ]);
        }, 3000);

        return () => clearTimeout(timer);
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        // Aquí puedes enviar formData a tu backend o realizar otra acción
        console.log('Datos del nuevo pedido:', formData);
        // Simulación de agregar nuevo pedido
        const newOrder = {
            id: orders.length + 1,
            ...formData
        };
        setOrders([...orders, newOrder]);
        // Limpiar formulario después de agregar pedido
        setFormData({
            customerName: '',
            productName: '',
            quantity: 0,
            price: 0,
            status: ''
        });
    };

    const handleDelete = (id) => {
        // Filtrar pedidos para eliminar el que tiene el id proporcionado
        const updatedOrders = orders.filter(order => order.id !== id);
        setOrders(updatedOrders);
    };

    const handleUpdate = (id) => {
        // Simulación de actualización del pedido
        const updatedOrders = orders.map(order => {
            if (order.id === id) {
                return { ...order, status: 'Actualizado' };
            }
            return order;
        });
        setOrders(updatedOrders);
    };

    return (
        <div>
            {loading ? <Loading /> : null}
            <CompanyMenu className="nav-menu" />
            <div className="body-orders">
                <h2>Lista de Pedidos</h2>
                <form className="form-order" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Nombre del Cliente:</label>
                        <input
                            type="text"
                            name="customerName"
                            value={formData.customerName}
                            onChange={handleChange}
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label>Nombre del Producto:</label>
                        <input
                            type="text"
                            name="productName"
                            value={formData.productName}
                            onChange={handleChange}
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label>Cantidad:</label>
                        <input
                            type="number"
                            name="quantity"
                            value={formData.quantity}
                            onChange={handleChange}
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label>Precio:</label>
                        <input
                            type="number"
                            name="price"
                            value={formData.price}
                            onChange={handleChange}
                            required
                        />
                    </div>
                    <div className="form-group">
                        <label>Estado:</label>
                        <select
                            name="status"
                            value={formData.status}
                            onChange={handleChange}
                            required
                        >
                            <option value="">Seleccione</option>
                            <option value="Pendiente">Pendiente</option>
                            <option value="En proceso">En proceso</option>
                            <option value="Completado">Completado</option>
                        </select>
                    </div>
                    <button type="submit">Agregar Pedido</button>
                </form>
                <table className="order-table">
                    <thead>
                        <tr>
                            <th>ID</th>
                            <th>Cliente</th>
                            <th>Producto</th>
                            <th>Cantidad</th>
                            <th>Precio</th>
                            <th>Estado</th>
                            <th>Acciones</th>
                        </tr>
                    </thead>
                    <tbody>
                        {orders.map(order => (
                            <tr key={order.id}>
                                <td>{order.id}</td>
                                <td>{order.customerName}</td>
                                <td>{order.productName}</td>
                                <td>{order.quantity}</td>
                                <td>{order.price}</td>
                                <td>{order.status}</td>
                                <td>
                                    <button onClick={() => handleUpdate(order.id)}>Actualizar</button>
                                    <button onClick={() => handleDelete(order.id)}>Eliminar</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default CompanyOrders;
